using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to ToolStripSystemRenderer.
    // Explicitly set the renderer to preserve the .NET 8 professional look.
    public StatusStrip CreateStatusStrip()
    {
        var strip = new StatusStrip();
        strip.RenderMode = ToolStripRenderMode.Professional;
        return strip;
    }

    // .NET 9 breaking change: DropDownControl no longer accepts null.
    // Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control? control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }

    // .NET 9 breaking change: GetObject on COM interop now throws on failure
    // instead of returning null. Use Marshal.GetObjectForIUnknown with try/catch.
    [DllImport("ole32.dll")]
    private static extern int CoCreateInstance(
        ref Guid rclsid, IntPtr pUnkOuter, uint dwClsContext, ref Guid riid, out IntPtr ppv);

    public object? CreateComObject(Guid clsid)
    {
        Guid iUnknown = new("00000000-0000-0000-C000-000000000046");
        int hr = CoCreateInstance(ref clsid, IntPtr.Zero, 1, ref iUnknown, out IntPtr punk);
        if (hr != 0 || punk == IntPtr.Zero)
            return null;

        try
        {
            return Marshal.GetObjectForIUnknown(punk);
        }
        catch (COMException)
        {
            return null;
        }
        finally
        {
            Marshal.Release(punk);
        }
    }
}

